import { cn } from "@/lib/utils";
import { POLITICS_ICONS, type PoliticsIconName } from "./politics-icons.generated";

export type { PoliticsIconName };

/**
 * A single warm-duotone politics icon, sliced from the shared sprite sheet
 * (generated by web/scripts/politics-icons). Shares the exact STYLE of the
 * housing and economy icon sets, so all three read on the warm-white and
 * terminal-black themes and a politician card can sit beside a housing one.
 *
 * WHAT THE SUBJECTS MAY DEPICT IS AN EDITORIAL DECISION, NOT A STYLE ONE.
 * These icons render beside NAMED parliamentarians, and
 * docs/influence-editorial-standards.md rule 1 lists iconography as one of the
 * ways a page of true facts still carries an imputation. The set therefore holds
 * no money, no warning mark, no gavel or scales, and no trophy — see the header
 * of web/scripts/politics-icons/icon-set.config.mjs, which is enforced by
 * politics-icon-subjects.test.ts.
 *
 * SERVER-SAFE BY CONSTRUCTION: this file imports `cn` and a generated coords
 * table, and nothing else. It must never reach for `compliance.tsx` or a
 * `~/gen/…` protobuf module — a client island composing it would then take the
 * whole static build down with a minified "Element type is invalid"
 * (client-boundary.test.ts exists because that has happened twice).
 *
 * @param name  icon id from the manifest (autocompleted)
 * @param size  rendered px (square); the sprite cell is downscaled to this
 * @param title pass ONLY for a standalone, label-less icon — see below
 */
export function PoliticsIcon({
  name,
  size = 16,
  className,
  title,
}: {
  name: PoliticsIconName;
  size?: number;
  className?: string;
  title?: string;
}) {
  const pos = POLITICS_ICONS.icons[name];
  if (!pos) return null;
  const scale = size / POLITICS_ICONS.cell;
  // Icons always sit beside their text label, so they're decorative by default
  // (aria-hidden) — matching <EconomyIcon>'s convention. A screen reader must
  // hear "Gift", not "wrapped parcel Gift", exactly as register-items.test.ts
  // already requires of the emoji this replaces. Pass `title` only for a
  // genuinely standalone, label-less icon.
  const a11y = title ? { role: "img", "aria-label": title } : { "aria-hidden": true };
  return (
    <span
      {...a11y}
      className={cn("inline-block shrink-0 align-[-0.15em]", className)}
      style={{
        width: size,
        height: size,
        backgroundImage: `url(${POLITICS_ICONS.sheet})`,
        backgroundRepeat: "no-repeat",
        backgroundSize: `${POLITICS_ICONS.width * scale}px ${POLITICS_ICONS.height * scale}px`,
        backgroundPosition: `-${pos.x * scale}px -${pos.y * scale}px`,
      }}
    />
  );
}
